package gadomancymodern.node;
import gadomancymodern.Gadomancy;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
import tc4revival.aspect.*;
import tc4revival.content.*;
/** Original multiblock, wand buffer and separate manipulation/portal transactions. */
public class NodeManipulatorEntity extends ArcanePedestalBlockEntity implements RevealedAspectContainer {
    public boolean formed,working;public String mode="";public int workTick;public AspectAmounts work=new AspectAmounts();public final java.util.List<BlockPos> pedestals=new java.util.ArrayList<>();
    public NodeManipulatorEntity(BlockPos pos,BlockState state){super(Gadomancy.MANIPULATOR_BE.get(),pos,state);}
    public boolean portal(){return mode.equals("portal");}
    public boolean structure(boolean built){if(!(level.getBlockEntity(worldPosition.above(2)) instanceof AuraNodeBlockEntity))return false;var focus=level.getBlockState(worldPosition.above());String next=focus.is(Gadomancy.RANDOMIZATION_FOCUS.get())?"node":focus.is(Gadomancy.PORTAL_FOCUS.get())?"portal":"";if(next.isEmpty()||built&&!mode.equals(next))return false;for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})for(int y=0;y<2;y++){var at=worldPosition.offset(x,y,z);if(!level.hasChunkAt(at))return false;var required=built?(y==0?Gadomancy.PILLAR.get():Gadomancy.PILLAR_TOP.get()):(y==0?TCEldritch.PEDESTAL_STONE.get():TCEldritch.STONE.get());if(!level.getBlockState(at).is(required))return false;}if(next.equals("portal")&&!eyes(false))return false;mode=next;return true;}
    public boolean eyes(boolean requireItems){pedestals.clear();for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++){for(int y=-5;y<=10;y++){var at=worldPosition.offset(x,y,z);if(!level.hasChunkAt(at))continue;if(level.getBlockEntity(at) instanceof gadomancymodern.compressor.AncientPedestalEntity tile&&(!requireItems||tile.getItem(0).is(TCEldritch.ELDRITCH_EYE.get()))){pedestals.add(at);break;}}if(pedestals.size()>=4)return true;}return false;}
    public boolean form(Player player,InteractionHand hand){var stack=player.getItemInHand(hand);if(formed||!(player instanceof ServerPlayer server)||!(stack.getItem() instanceof CastingWandItem wand)||!structure(false)||!thaumcraft.api.ThaumcraftApiHelper.isResearchComplete(server,"gadomancy:"+(portal()?"e_portal_creator":"node_manipulator")))return false;for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})for(int y=0;y<2;y++)if(!level.mayInteract(player,worldPosition.offset(x,y,z)))return false;var cost=new java.util.LinkedHashMap<Aspect,Integer>();for(var aspect:thaumcraft.api.aspects.AspectSelection.select(TCAspects.catalog(),thaumcraft.api.aspects.AspectSelection.NODE_MANIPULATION))cost.put(aspect,portal()?150:100);if(!wand.consumeForPlayer(stack,player,cost,true,true,true))return false;formed=true;for(int x:new int[]{-1,1})for(int z:new int[]{-1,1}){var at=worldPosition.offset(x,0,z);int facing=x==1?(z==1?5:4):(z==1?3:2);level.setBlock(at,Gadomancy.PILLAR.get().defaultBlockState().setValue(ManipulatorPillarBlock.ORIENTATION,facing),3);level.setBlock(at.above(),Gadomancy.PILLAR_TOP.get().defaultBlockState(),3);NodeVisualNetwork.runes((ServerLevel)level,at,0);}sync();return true;}
    public void tick(){if(level==null||level.isClientSide||!formed)return;if(!structure(true)){breakStructure();return;}if(!working){if(!drain()){int minimum=portal()?120:70;if(thaumcraft.api.aspects.AspectSelection.select(TCAspects.catalog(),thaumcraft.api.aspects.AspectSelection.NODE_MANIPULATION).stream().allMatch(a->work.amount(a)>=minimum)){working=true;sync();}}return;}if(portal()&&!eyes(true)){if(workTick>1){working=false;workTick=0;work=new AspectAmounts();sync();}return;}workTick++;int duration=portal()?400:300;if(workTick<duration){if(workTick%16==0)NodeVisualNetwork.runes((ServerLevel)level,worldPosition,portal()?1:0);if(level.random.nextInt(portal()?2:4)==0){int x=level.random.nextBoolean()?1:-1,z=level.random.nextBoolean()?1:-1;NodeVisualNetwork.bolt((ServerLevel)level,worldPosition.getCenter().add(0,2,0),worldPosition.getCenter().add(x*.7,1.4,z*.7),portal()?2:0);}if(portal()){if((workTick&7)==0)NodeVisualNetwork.runes((ServerLevel)level,pedestals.get((workTick>>3)&3),1);if(level.random.nextInt(4)==0)NodeVisualNetwork.bolt((ServerLevel)level,worldPosition.getCenter().add(0,2,0),pedestals.get(level.random.nextInt(4)).getCenter().add(0,1,0),2);}return;}if(portal())completePortal();else mutate();workTick=0;working=false;work=new AspectAmounts();sync();}
    public boolean drain(){var stack=getItem(0);if(!(stack.getItem() instanceof CastingWandItem wand))return false;var primals=new java.util.ArrayList<>(thaumcraft.api.aspects.AspectSelection.select(TCAspects.catalog(),thaumcraft.api.aspects.AspectSelection.NODE_MANIPULATION));for(int i=primals.size()-1;i>0;i--){int j=level.random.nextInt(i+1);var a=primals.get(i);primals.set(i,primals.get(j));primals.set(j,a);}for(var a:primals)if(work.amount(a)<(portal()?150:120)&&wand.vis(stack,a)>=100&&wand.consume(stack,java.util.Map.of(a,100),ignored->1,false,true,level)){work.add(a,1);NodeVisualNetwork.wandDrain((ServerLevel)level,worldPosition,a.color());sync();return true;}return false;}
    public void mutate(){if(!(level.getBlockEntity(worldPosition.above(2)) instanceof AuraNodeBlockEntity node))return;int sum=0;for(var a:thaumcraft.api.aspects.AspectSelection.select(TCAspects.catalog(),thaumcraft.api.aspects.AspectSelection.NODE_MANIPULATION))sum+=work.amount(a)-70;int chance=(int)((sum/6f)/50*100);var state=new NodeManipulations.State(TCAspects.catalog(),node.permanentBase(),node.portableCharge(),node.permanentType(),node.permanentModifier(),node instanceof ExtendedNodeEntity ext&&ext.growing(),gadomancymodern.aura.AuraEffectsConfig.ADDITIONAL_NODES.get());NodeManipulations.mutate(state,level.random,chance);if(state.growing&&!(node instanceof ExtendedNodeEntity))node=ExtendedNodeEntity.convert((ServerLevel)level,node.getBlockPos());if(node==null)return;node.configure(state.base,state.type,state.modifier,node.nodeId(),true);for(var a:state.charge.aspects())node.addCharge(a,Math.min(state.base.amount(a),Math.max(0,state.charge.amount(a))));if(node instanceof ExtendedNodeEntity ext){ext.extension=state.growing?"gadomancy:growing":"";if(ext.growing())ext.discover("growing",12);}node.sync();NodeVisualNetwork.sparkles((ServerLevel)level,node.getBlockPos());}
    protected void completePortal(){for(var pos:pedestals)if(level.getBlockEntity(pos) instanceof gadomancymodern.compressor.AncientPedestalEntity tile){tile.setItem(0,ItemStack.EMPTY);NodeVisualNetwork.sparkles((ServerLevel)level,pos);}level.setBlock(worldPosition.above(2),Gadomancy.ADDITIONAL_PORTAL.get().defaultBlockState(),3);}
    public void breakStructure(){if(!formed)return;formed=false;for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})for(int y=0;y<2;y++){var at=worldPosition.offset(x,y,z);if(level.getBlockState(at).is(y==0?Gadomancy.PILLAR.get():Gadomancy.PILLAR_TOP.get()))level.setBlock(at,(y==0?TCEldritch.PEDESTAL_STONE.get():TCEldritch.STONE.get()).defaultBlockState(),3);}var stack=removeItemNoUpdate(0);if(!stack.isEmpty())net.minecraft.world.level.block.Block.popResource(level,worldPosition,stack);work=new AspectAmounts();mode="";workTick=0;working=false;sync();}
    @Override public boolean canPlaceItem(int slot,ItemStack stack){return slot==0&&stack.getItem() instanceof CastingWandItem;}
    @Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction face){return formed&&isEmpty()&&canPlaceItem(slot,stack);}
    @Override public AspectAmounts revealedAspects(){return work.copy();}
    @Override protected void saveAdditional(CompoundTag tag){super.saveAdditional(tag);tag.putBoolean("Formed",formed);tag.putBoolean("Working",working);tag.putString("Mode",mode);tag.putInt("WorkTick",workTick);var values=new CompoundTag();AspectNbt.write(values,work);tag.put("Work",values);}
    @Override public void load(CompoundTag tag){super.load(tag);formed=tag.getBoolean("Formed");working=tag.getBoolean("Working");mode=tag.getString("Mode");workTick=Math.max(0,Math.min(400,tag.getInt("WorkTick")));work=AspectNbt.read(tag.getCompound("Work"),TCAspects.catalog()).amounts();}
}
